// src/components/Equipment.js
import React, { useState } from 'react';
import styled from 'styled-components';
import Modal from 'react-modal';

// Grid styling for layout
const EquipmentGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-top: 20px;
`;

const EquipmentItem = styled.div`
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 15px;
  background-color: ${({ isSelected }) => (isSelected ? '#d1e7dd' : '#fff')};
  text-align: center;
  cursor: pointer;
  transition: box-shadow 0.3s ease, transform 0.3s ease;

  &:hover {
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
    transform: scale(1.02);
  }
`;

const EquipmentImage = styled.img`
  width: 100%;
  height: 180px;
  object-fit: cover;
  border-radius: 8px;
  margin-bottom: 10px;
`;

const ItemName = styled.h3`
  margin: 5px 0;
  font-size: 1.1rem;
  color: #333;
`;

const ItemPrice = styled.p`
  font-size: 1rem;
  color: #4caf50;
  font-weight: bold;
  margin: 5px 0;
`;

// Modal styling
const customStyles = {
  content: {
    top: '50%',
    left: '50%',
    right: 'auto',
    bottom: 'auto',
    marginRight: '-50%',
    transform: 'translate(-50%, -50%)',
    padding: '30px',
    width: '60%',
    maxWidth: '600px',
    borderRadius: '10px',
    boxShadow: '0 10px 30px rgba(0, 0, 0, 0.2)',
    border: 'none',
  },
};

const ModalContent = styled.div`
  text-align: center;
`;

const ModalImage = styled.img`
  max-width: 100%;
  max-height: 300px;
  margin-bottom: 15px;
  object-fit: contain;
  border-radius: 8px;
`;

const ModalHeader = styled.h2`
  margin-top: 0;
  color: #333;
`;

const ModalCloseButton = styled.button`
  background-color: #f44336;
  color: white;
  border: none;
  padding: 8px 12px;
  border-radius: 5px;
  cursor: pointer;
  float: right;

  &:hover {
    background-color: #d32f2f;
  }
`;

const SelectButton = styled.button`
  background-color: ${({ isSelected }) => (isSelected ? '#f44336' : '#4caf50')};
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: 5px;
  cursor: pointer;
  margin-top: 15px;
  transition: background-color 0.3s ease;

  &:hover {
    background-color: ${({ isSelected }) => (isSelected ? '#d32f2f' : '#388e3c')};
  }
`;

const Equipment = ({ equipment, handleSelect, selectedItems = [] }) => {
  const [modalItem, setModalItem] = useState(null);

  const openModal = (item) => setModalItem(item);
  const closeModal = () => setModalItem(null);

  const isSelected = (item) =>
    selectedItems.some((selected) => selected.id === item.id);

  return (
    <>
      <EquipmentGrid>
        {equipment.map((item) => (
          <EquipmentItem
            key={item.id}
            isSelected={isSelected(item)}
            onClick={() => openModal(item)}
          >
            <EquipmentImage src={item.Image_URL} alt={item.Name} />
            <ItemName>{item.Name}</ItemName>
            <p>Brand: {item.Brand}</p>
            <ItemPrice>${item.Price}</ItemPrice>
          </EquipmentItem>
        ))}
      </EquipmentGrid>

      {modalItem && (
        <Modal
          isOpen={!!modalItem}
          onRequestClose={closeModal}
          style={customStyles}
        >
          <ModalContent>
            <ModalHeader>
              {modalItem.Name}
              <ModalCloseButton onClick={closeModal}>Close</ModalCloseButton>
            </ModalHeader>

            <ModalImage src={modalItem.Image_URL} alt={modalItem.Name} />
            <p><strong>Brand:</strong> {modalItem.Brand}</p>
            <p><strong>Price:</strong> ${modalItem.Price}</p>

            {modalItem.Details && (
              <>
                <h4>Details</h4>
                <ul>
                  {modalItem.Details.map((detail, index) => (
                    <li key={index}>{detail}</li>
                  ))}
                </ul>
              </>
            )}

            {modalItem.Tech_Specs && (
              <>
                <h4>Tech Specs</h4>
                <ul>
                  {Object.entries(modalItem.Tech_Specs).map(([key, value]) => (
                    <li key={key}>
                      <strong>{key}:</strong> {value}
                    </li>
                  ))}
                </ul>
              </>
            )}

            <a
              href={modalItem.Link}
              target="_blank"
              rel="noopener noreferrer"
              style={{ display: 'block', marginTop: '10px' }}
            >
              View Product Page
            </a>

            <SelectButton
              onClick={() => {
                handleSelect(modalItem);
                closeModal();
              }}
              isSelected={isSelected(modalItem)}
            >
              {isSelected(modalItem) ? 'Remove from Selection' : 'Add to Selection'}
            </SelectButton>
          </ModalContent>
        </Modal>
      )}
    </>
  );
};

export default Equipment;
